begin;
-- LC editorial migration — módulo 5: Funções, listas e solução completa
update nexora.lessons set objective='Criar funções para encapsular tarefas com responsabilidade clara, escolhendo nomes que expressem a transformação realizada e evitando duplicação de lógica.',estimated_minutes=22,content='[{"type":"story","title":"Quando uma regra aparece pela terceira vez, ela está pedindo um nome","body":"Imagine que o cálculo de frete apareça no carrinho, no fechamento do pedido e na tela administrativa. Copiar a mesma regra em três lugares parece rápido, mas qualquer mudança futura precisa ser repetida com perfeição.\n\nFunções permitem dar um nome a uma tarefa e reutilizar a mesma lógica em diferentes pontos."},{"type":"concept","title":"Função encapsula uma tarefa sob um nome","body":"Uma função agrupa instruções que realizam uma responsabilidade específica. Quem usa a função não precisa repetir os passos; chama a tarefa pelo nome.\n\nUma boa função costuma responder a uma pergunta clara: calcular média, validar documento, calcular frete, formatar nome."},{"type":"mechanics","title":"Uma função saudável tende a ter","items":["Um nome que descreve a ação.","Uma responsabilidade principal.","Entradas explícitas quando precisa de dados externos.","Um resultado ou efeito compreensível.","Tamanho pequeno o suficiente para ser testada isoladamente."]},{"type":"example","title":"De bloco repetido a tarefa reutilizável","body":"Em vez de repetir “somar itens → aplicar desconto → devolver total” em vários lugares, podemos criar uma função `calcularTotalPedido` e centralizar a regra.\n\nSe a política mudar, existe um ponto principal para revisar."},{"type":"guided","title":"Qual nome comunica melhor uma função?","question":"Uma função recebe duas notas e calcula a média. Qual nome é mais claro?","options":["fazCoisa","calc","calcularMedia","x"],"answer":2,"feedback":"Correto. O nome descreve diretamente a transformação realizada.","feedback_incorrect":"Prefira um verbo e o conceito de domínio que a função representa."},{"type":"mistake","title":"Função não é gaveta para qualquer código","body":"Uma função chamada `processarTudo` que valida, salva, envia e-mail, gera relatório e altera interface não reduz complexidade; apenas a esconde. Quando responsabilidades diferentes crescem juntas, decomponha."},{"type":"recap","items":["Funções dão nomes a tarefas reutilizáveis.","Centralizar regras reduz duplicação.","Nome e responsabilidade devem ser claros.","Funções pequenas são mais fáceis de testar e combinar."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Funções, listas e solução completa","concept":"Criar funções para encapsular tarefas com responsabilidade clara, escolhendo nomes que expressem a transformação realizada e evitando duplicação de lógica.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Qual função tem responsabilidade mais clara?","options":["processarTudo()","calcularFrete(valorPedido, cep)","fazCoisa()","executarSistemaCompleto()"],"answer":1,"feedback":"Correto. O nome e as entradas deixam a tarefa explícita.","feedback_incorrect":"Procure a função cuja responsabilidade pode ser explicada em uma frase curta."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) and position=1;
update nexora.lessons set objective='Distinguir parâmetros de argumentos e projetar funções que recebam somente os dados necessários para executar sua responsabilidade.',estimated_minutes=22,content='[{"type":"story","title":"Uma função reutilizável não pode depender de um único caso","body":"Uma função que calcula desconto precisa funcionar para compras diferentes. Para isso, ela deve receber os valores que variam, em vez de depender de números fixos escondidos dentro da implementação.\n\nParâmetros representam as entradas esperadas pela função; argumentos são os valores reais fornecidos em cada chamada."},{"type":"concept","title":"Parâmetro define o contrato; argumento preenche o contrato","body":"Em `calcularTotal(preco, quantidade)`, `preco` e `quantidade` são parâmetros da função. Em `calcularTotal(120, 2)`, 120 e 2 são argumentos usados naquela execução.\n\nEssa separação permite que a mesma função trabalhe com diferentes dados."},{"type":"example","title":"Uma função, vários pedidos","body":"`calcularTotal(120, 2)` pode produzir 240.\n`calcularTotal(50, 3)` pode produzir 150.\n\nA regra é a mesma; os argumentos mudam."},{"type":"mechanics","title":"Escolha parâmetros pelo que a função realmente precisa","items":["Evite depender de dados globais quando uma entrada explícita é mais clara.","Não passe informações que a função nunca usa.","Use nomes de parâmetros que expliquem o papel esperado.","Valide argumentos quando o domínio exigir limites ou formatos."]},{"type":"guided","title":"Parâmetro ou argumento?","question":"Na chamada `calcularFrete(350, \"01000-000\")`, o valor 350 é:","options":["Um parâmetro declarado na função.","Um argumento fornecido na chamada.","O nome da função.","Uma constante obrigatória."],"answer":1,"feedback":"Correto. É um valor concreto usado naquela execução.","feedback_incorrect":"Parâmetro é o nome definido pela função; argumento é o valor entregue na chamada."},{"type":"mistake","title":"Muitos parâmetros podem indicar responsabilidade demais","body":"Uma função com dez ou quinze parâmetros pode estar tentando resolver mais de uma tarefa. Nem sempre é erro, mas é um sinal para revisar a modelagem e talvez agrupar dados relacionados."},{"type":"recap","items":["Parâmetros descrevem entradas esperadas.","Argumentos são valores concretos da chamada.","Entradas explícitas aumentam reutilização e testabilidade.","Quantidade excessiva de parâmetros merece revisão."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Funções, listas e solução completa","concept":"Distinguir parâmetros de argumentos e projetar funções que recebam somente os dados necessários para executar sua responsabilidade.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Em `calcularMedia(nota1, nota2)`, o que `nota1` representa na definição da função?","options":["Parâmetro.","Argumento específico da chamada.","Resultado final.","Laço."],"answer":0,"feedback":"Correto. O nome representa uma entrada que será preenchida em cada chamada.","feedback_incorrect":"Na definição da função, os nomes das entradas são parâmetros."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) and position=2;
update nexora.lessons set objective='Usar retorno para entregar resultados reutilizáveis a outras partes da solução, diferenciando retornar um valor de apenas exibi-lo.',estimated_minutes=23,content='[{"type":"story","title":"Mostrar um resultado não é o mesmo que entregá-lo","body":"Uma função calcula o total de uma compra e imprime “R$ 240”. Depois, outra parte precisa aplicar desconto sobre esse total. Se a função apenas exibiu o número, talvez o restante do programa não tenha recebido o valor para continuar o cálculo.\n\nRetorno é o mecanismo usado para entregar um resultado a quem chamou a função."},{"type":"concept","title":"Retorno transforma a função em parte de uma expressão maior","body":"Uma função que retorna um valor pode ser usada em cálculos, decisões, outras funções ou armazenamento. O resultado volta para o ponto da chamada.\n\nExibir, registrar ou imprimir são efeitos; retornar é fornecer um valor reutilizável."},{"type":"example","title":"Compondo cálculos","body":"`total = calcularTotal(120, 2)`\nDepois:\n`desconto = calcularDesconto(total)`\n\nO retorno de uma função vira argumento da próxima. Essa composição é uma das bases da construção de soluções maiores."},{"type":"comparison","title":"Retornar × imprimir","items":["Retornar: entrega o valor ao código chamador.","Imprimir: mostra algo ao usuário ou console.","Uma função pode fazer ambos, mas são responsabilidades diferentes.","Para reutilizar um cálculo, o retorno normalmente é essencial."]},{"type":"guided","title":"O que precisa ser retornado?","question":"Uma função `calcularMedia` será usada depois para decidir aprovação. O que ela deve fornecer?","options":["Apenas a mensagem “calculado”.","O valor numérico da média.","O nome da função.","Um laço sem resultado."],"answer":1,"feedback":"Correto. A decisão posterior precisa do valor calculado.","feedback_incorrect":"Pense no dado que outra parte do programa precisa reutilizar."},{"type":"mistake","title":"Retornar cedo demais pode pular regras","body":"Em algumas linguagens, o retorno encerra a função naquele ponto. Se colocado antes de validações ou cálculos necessários, parte da lógica deixa de executar. Leia o fluxo até cada saída possível."},{"type":"recap","items":["Retorno entrega um valor ao chamador.","Imprimir e retornar têm finalidades diferentes.","Resultados retornados podem alimentar outras funções.","Cada caminho relevante precisa retornar um resultado coerente."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Funções, listas e solução completa","concept":"Usar retorno para entregar resultados reutilizáveis a outras partes da solução, diferenciando retornar um valor de apenas exibi-lo.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Por que `return total` é mais reutilizável do que apenas `print(total)`?","options":["Porque o valor pode ser usado por outra parte da solução.","Porque imprimir sempre causa erro.","Porque return transforma número em texto.","Porque return elimina todos os parâmetros."],"answer":0,"feedback":"Correto. O retorno entrega o valor para composição posterior.","feedback_incorrect":"A pergunta central é: outra parte do programa consegue usar o resultado?"},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) and position=3;
update nexora.lessons set objective='Usar listas para representar coleções de tamanho variável, acessando, percorrendo e validando elementos sem criar uma variável separada para cada item.',estimated_minutes=23,content='[{"type":"story","title":"Três notas cabem em três variáveis; trinta já mostram o problema","body":"Criar `nota1`, `nota2`, `nota3` parece aceitável para um exemplo pequeno. Mas uma turma real pode ter dezenas de notas, e a quantidade pode mudar. O algoritmo não deve precisar de uma nova variável para cada item.\n\nListas agrupam valores relacionados em uma única estrutura."},{"type":"concept","title":"Lista é uma coleção ordenada de elementos","body":"Uma lista pode conter zero, um ou muitos itens. Os elementos podem ser acessados por posição e percorridos por laços.\n\nA coleção permite que o algoritmo lide com quantidade variável mantendo a mesma lógica."},{"type":"example","title":"Notas de uma turma","body":"`notas = [8, 7, 9]` representa três valores relacionados. Podemos percorrer a lista para somar, contar aprovados, encontrar maior nota ou calcular média.\n\nSe uma quarta nota for adicionada, a estrutura continua adequada."},{"type":"mechanics","title":"Perguntas importantes sobre coleções","items":["A lista pode estar vazia?","A ordem dos elementos importa?","Existe risco de acessar posição inexistente?","A operação precisa alterar a lista original ou apenas produzir outro resultado?"]},{"type":"guided","title":"Por que usar lista?","question":"Qual cenário favorece uma lista?","options":["Guardar uma única idade fixa.","Guardar quantidade variável de produtos de um carrinho.","Representar uma constante de imposto.","Executar somente uma comparação."],"answer":1,"feedback":"Correto. A quantidade de itens pode mudar sem alterar a estrutura do algoritmo.","feedback_incorrect":"Procure dados relacionados que podem aparecer em quantidade variável."},{"type":"mistake","title":"Coleção vazia é um estado válido","body":"Algoritmos frequentemente assumem que existe pelo menos um item. Isso pode quebrar cálculo de média, busca do primeiro elemento ou acesso por posição. Teste explicitamente a lista vazia."},{"type":"recap","items":["Listas agrupam valores relacionados.","A quantidade pode variar sem reescrever o algoritmo.","Laços percorrem os elementos.","Lista vazia e posições inválidas precisam ser tratadas."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Funções, listas e solução completa","concept":"Usar listas para representar coleções de tamanho variável, acessando, percorrendo e validando elementos sem criar uma variável separada para cada item.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Qual vantagem principal uma lista oferece sobre `produto1`, `produto2`, `produto3`...?","options":["Permite lidar com quantidade variável usando a mesma lógica.","Transforma todos os dados em constantes.","Impede qualquer repetição.","Elimina a necessidade de validação."],"answer":0,"feedback":"Correto. A coleção desacopla a lógica da quantidade fixa de variáveis.","feedback_incorrect":"Pense no que acontece quando a quantidade de produtos muda."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) and position=4;
update nexora.lessons set objective='Distinguir as intenções de buscar, filtrar e transformar coleções e escolher o padrão que produz o tipo correto de resultado para cada problema.',estimated_minutes=25,content='[{"type":"story","title":"Três perguntas diferentes sobre a mesma lista","body":"Com uma lista de produtos, podemos perguntar: “qual produto tem id 42?”, “quais custam mais de R$ 500?” ou “quais são os nomes em maiúsculas?”. A entrada é a mesma coleção, mas o resultado esperado muda completamente.\n\nReconhecer a intenção evita laços que fazem várias coisas ao mesmo tempo."},{"type":"concept","title":"Buscar, filtrar e transformar têm resultados diferentes","body":"Buscar procura um item ou posição que satisfaça um critério. Filtrar mantém um subconjunto de elementos. Transformar produz uma nova representação de cada elemento.\n\nAntes de escolher a técnica, defina o formato da saída."},{"type":"comparison","title":"Mesma lista, três intenções","items":["Buscar: encontrar o cliente com CPF específico.","Filtrar: manter somente clientes ativos.","Transformar: gerar uma lista apenas com os nomes.","É possível combinar operações, mas cada etapa deve continuar compreensível."]},{"type":"example","title":"Produtos de uma loja","body":"Entrada: três produtos com nome, preço e categoria.\n\nBuscar → um produto por id.\nFiltrar → todos da categoria “informática”.\nTransformar → uma nova lista com `nome + preço formatado`."},{"type":"guided","title":"Qual intenção produz subconjunto?","question":"Queremos todos os pedidos com status “pendente”. Qual padrão corresponde melhor?","options":["Buscar um único item.","Filtrar a coleção.","Transformar cada valor em outro formato.","Retornar sempre o primeiro pedido."],"answer":1,"feedback":"Correto. O resultado pode conter zero, um ou vários itens que satisfazem a condição.","feedback_incorrect":"Procure a operação que mantém apenas os elementos aprovados pelo critério."},{"type":"mistake","title":"Um laço que busca, filtra, soma e altera ao mesmo tempo fica frágil","body":"Combinar muitas intenções dentro do mesmo bloco pode economizar linhas, mas aumenta a dificuldade de testar. Quando as responsabilidades são independentes, separe etapas ou funções."},{"type":"recap","items":["Buscar procura um item.","Filtrar produz um subconjunto.","Transformar cria nova representação.","O formato de saída ajuda a escolher o padrão."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Funções, listas e solução completa","concept":"Distinguir as intenções de buscar, filtrar e transformar coleções e escolher o padrão que produz o tipo correto de resultado para cada problema.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Queremos uma lista contendo somente os valores das vendas concluídas. Qual intenção principal é necessária primeiro?","options":["Filtrar pelas concluídas.","Buscar apenas a primeira venda.","Ignorar status.","Alterar todos os status."],"answer":0,"feedback":"Correto. Primeiro selecionamos o subconjunto que satisfaz o critério.","feedback_incorrect":"A saída precisa conter vários itens, mas apenas os que atendem à condição."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) and position=5;
update nexora.lessons set objective='Compor uma solução maior a partir de funções, listas, decisões e repetições pequenas, definindo fluxo, contratos e testes para cada etapa.',estimated_minutes=26,content='[{"type":"story","title":"Fundamentos viram sistema quando começam a conversar","body":"Até aqui vimos conceitos separados: dados, decisões, laços, funções e listas. Um problema real combina todos eles. Um sistema de notas, por exemplo, recebe uma lista, valida valores, calcula média, classifica situação e apresenta resultado.\n\nCompor uma solução significa conectar partes pequenas sem perder a capacidade de entender e testar cada uma."},{"type":"concept","title":"Construa um fluxo de responsabilidades","body":"Em vez de escrever um bloco enorme, decomponha o problema em etapas e associe cada etapa a uma responsabilidade. Funções podem representar transformações; listas carregam coleções; laços percorrem; condições selecionam caminhos.\n\nA saída de uma etapa se torna entrada da próxima."},{"type":"example","title":"Sistema de notas","items":["`validarNotas(notas)` confirma domínio 0–10.","`calcularMedia(notas)` percorre e acumula valores.","`classificar(media, frequencia)` escolhe situação.","`montarResultado(...)` prepara a saída final."]},{"type":"mechanics","title":"Integração sem perder testabilidade","items":["Teste funções menores isoladamente.","Defina o contrato de entrada e saída de cada etapa.","Teste também o fluxo completo.","Evite estado compartilhado sem necessidade.","Quando uma etapa falhar, saiba onde interromper ou retornar erro."]},{"type":"guided","title":"Qual decomposição é mais testável?","question":"Qual organização facilita localizar falhas em um sistema de pedidos?","options":["Um único bloco `processarTudo`.","Validar itens → calcular total → aplicar desconto → gerar resumo.","Misturar interface, regra e armazenamento sem etapas.","Copiar a lógica em várias telas."],"answer":1,"feedback":"Correto. Cada responsabilidade pode ser compreendida e testada separadamente.","feedback_incorrect":"Procure uma sequência de partes pequenas com entradas e resultados claros."},{"type":"professional_context","title":"Isso é a base de arquitetura de software","body":"Sistemas profissionais usam o mesmo princípio em escala maior: componentes, serviços, módulos e APIs dividem responsabilidades e se comunicam por contratos. A lógica aprendida aqui é o primeiro passo para entender essas arquiteturas."},{"type":"recap","items":["Soluções maiores são compostas por responsabilidades menores.","A saída de uma etapa alimenta a próxima.","Contratos claros facilitam teste e manutenção.","Integração precisa ser testada além das partes isoladas."]}]'::jsonb,lab_type='checkpoint',lab_config='{"module":"Funções, listas e solução completa","concept":"Compor uma solução maior a partir de funções, listas, decisões e repetições pequenas, definindo fluxo, contratos e testes para cada etapa.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Qual prática ajuda mais a diagnosticar um erro em uma solução composta?","options":["Ter funções e etapas com responsabilidades e contratos claros.","Escrever tudo em um único bloco.","Evitar testes isolados.","Compartilhar todas as variáveis globalmente."],"answer":0,"feedback":"Correto. Partes bem definidas reduzem a área de investigação.","feedback_incorrect":"Pense em como descobrir rapidamente qual etapa deixou de cumprir seu contrato."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) and position=6;
update nexora.lessons set objective='Projetar uma solução completa para triagem de atendimentos combinando validação, prioridade, repetição, funções e testes, produzindo um algoritmo reproduzível.',estimated_minutes=30,content='[{"type":"story","title":"Agora o problema chega sem indicar qual conceito usar","body":"Em situações reais ninguém pede: “use uma variável, depois um IF e depois um laço”. O pedido chega como necessidade. Seu trabalho é escolher as ferramentas adequadas.\n\nO desafio final simula isso: organizar uma fila de atendimentos usando os fundamentos do curso."},{"type":"concept","title":"Cenário: triagem de atendimentos","body":"Cada atendimento possui nome, idade, tipo de solicitação e horário de chegada. A regra deve classificar prioridade e produzir uma ordem de atendimento.\n\nConsidere, para o exercício, prioridade para pessoas com 60 anos ou mais e depois ordem de chegada dentro da mesma categoria."},{"type":"mechanics","title":"Decomponha antes de construir","items":["Validar os dados de cada atendimento.","Determinar se o atendimento é prioritário.","Separar ou ordenar os registros pela regra.","Produzir a fila final.","Contar quantos atendimentos são prioritários.","Testar casos comuns, limites e dados inválidos."]},{"type":"example","title":"Casos mínimos de teste","body":"Ana, 59 anos, chegada 09:00 → comum.\nBruno, 60 anos, chegada 09:05 → prioritário.\nCarla, 72 anos, chegada 08:50 → prioritário e deve vir antes de Bruno dentro da prioridade.\nIdade -2 → entrada inválida; não deve ser classificada normalmente."},{"type":"guided","title":"Qual caso testa a fronteira principal?","question":"Se a prioridade começa aos 60 anos, qual conjunto é mais informativo?","options":["20, 30, 40","59, 60, 61","70, 80, 90","Somente 60"],"answer":1,"feedback":"Correto. O conjunto pressiona exatamente a mudança da regra.","feedback_incorrect":"Teste logo abaixo, no limite e logo acima."},{"type":"mastery","title":"Sua solução final deve demonstrar","items":["Modelagem clara de entradas e saída.","Validação antes da regra de prioridade.","Condição correta na fronteira dos 60 anos.","Uso de coleção e repetição para vários atendimentos.","Funções ou etapas pequenas para responsabilidades diferentes.","Evidência de testes normais, limites e inválidos."]},{"type":"recap","items":["Você não precisa usar todos os conceitos em todo problema.","Escolha estruturas pelo papel que precisam cumprir.","Uma solução completa continua sendo um conjunto de partes testáveis.","O domínio aparece quando você consegue justificar as decisões do algoritmo."]}]'::jsonb,lab_type='logic',lab_config='{"module":"Funções, listas e solução completa","concept":"Projetar uma solução completa para triagem de atendimentos combinando validação, prioridade, repetição, funções e testes, produzindo um algoritmo reproduzível.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Na triagem, qual etapa deve acontecer antes de classificar prioridade?","options":["Validar os dados do atendimento.","Ordenar por idade sem verificar valores.","Gerar a saída final.","Ignorar entradas inválidas."],"answer":0,"feedback":"Correto. Regras de prioridade só devem receber dados válidos.","feedback_incorrect":"A classificação não é confiável enquanto a entrada puder estar fora do domínio."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-2026.08"}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) and position=7;
update nexora.questions set prompt='Qual função apresenta responsabilidade mais clara?',options='[{"id":"a","label":"processarTudo()"},{"id":"b","label":"calcularFrete(valorPedido, cep)"},{"id":"c","label":"fazCoisa()"},{"id":"d","label":"executarSistema()"}]'::jsonb,correct_answer='{"option_id":"b"}'::jsonb,feedback_correct='Correto. Nome e entradas comunicam a tarefa.',feedback_incorrect='Procure uma função que possa ser explicada em uma frase curta.',difficulty=1 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) order by a.created_at asc limit 1) and position=1;
update nexora.questions set prompt='Na definição `calcularTotal(preco, quantidade)`, `preco` é:',options='[{"id":"a","label":"Parâmetro."},{"id":"b","label":"Argumento concreto da chamada."},{"id":"c","label":"Retorno."},{"id":"d","label":"Laço."}]'::jsonb,correct_answer='{"option_id":"a"}'::jsonb,feedback_correct='Correto. É uma entrada definida pelo contrato da função.',feedback_incorrect='Na definição, os nomes das entradas são parâmetros.',difficulty=1 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) order by a.created_at asc limit 1) and position=2;
update nexora.questions set prompt='Por que retornar uma média é diferente de apenas imprimi-la?',options='[{"id":"a","label":"O retorno pode ser reutilizado por outra decisão ou cálculo."},{"id":"b","label":"Imprimir sempre é proibido."},{"id":"c","label":"Return transforma número em lista."},{"id":"d","label":"Não existe diferença."}]'::jsonb,correct_answer='{"option_id":"a"}'::jsonb,feedback_correct='Correto. O valor volta ao chamador e pode participar de outras etapas.',feedback_incorrect='Pense em quem precisa usar o resultado depois.',difficulty=2 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) order by a.created_at asc limit 1) and position=3;
update nexora.questions set prompt='Qual situação é mais adequada a uma lista?',options='[{"id":"a","label":"Quantidade variável de produtos em um carrinho."},{"id":"b","label":"Uma constante de imposto."},{"id":"c","label":"Uma única comparação."},{"id":"d","label":"Um valor que nunca muda."}]'::jsonb,correct_answer='{"option_id":"a"}'::jsonb,feedback_correct='Correto. A coleção lida naturalmente com quantidade variável.',feedback_incorrect='Procure vários valores relacionados cuja quantidade pode mudar.',difficulty=2 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) order by a.created_at asc limit 1) and position=4;
update nexora.questions set prompt='Queremos todos os clientes ativos de uma coleção. Qual intenção principal?',options='[{"id":"a","label":"Buscar apenas um."},{"id":"b","label":"Filtrar."},{"id":"c","label":"Transformar todos em texto."},{"id":"d","label":"Ignorar status."}]'::jsonb,correct_answer='{"option_id":"b"}'::jsonb,feedback_correct='Correto. Filtrar produz o subconjunto que satisfaz o critério.',feedback_incorrect='A saída pode conter zero, um ou vários elementos aprovados pela condição.',difficulty=2 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) order by a.created_at asc limit 1) and position=5;
update nexora.questions set prompt='Qual organização facilita testar uma solução de pedidos?',options='[{"id":"a","label":"Validar → calcular total → aplicar desconto → montar resultado."},{"id":"b","label":"Um bloco único processarTudo."},{"id":"c","label":"Variáveis globais para todas as etapas."},{"id":"d","label":"Copiar regras entre telas."}]'::jsonb,correct_answer='{"option_id":"a"}'::jsonb,feedback_correct='Correto. Responsabilidades separadas criam pontos claros de teste.',feedback_incorrect='Procure etapas com contratos e responsabilidades identificáveis.',difficulty=3 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) order by a.created_at asc limit 1) and position=6;
