select gen_random_uuid(),(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) order by a.created_at asc limit 1),'No desafio de triagem, qual caso testa melhor a fronteira de prioridade aos 60 anos?','multiple_choice','[{"id":"a","label":"20, 30, 40"},{"id":"b","label":"59, 60, 61"},{"id":"c","label":"70, 80, 90"},{"id":"d","label":"Somente 60"}]'::jsonb,'{"option_id":"b"}'::jsonb,'Correto. O conjunto exercita abaixo, limite e acima.','Fronteiras são testadas com valores ao redor da mudança de regra.',3,7
