update nexora.assessments set title='Checkpoint aplicado — Funções, listas e solução completa',pass_score=70,max_attempts=3 where id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) order by a.created_at asc limit 1);
update nexora.learning_resources set title='Apostila LC — Funções, listas e solução completa',summary='Revisão integrada de funções, parâmetros, retornos, coleções e composição de soluções.',content='{"editorial_version":"lc-editorial-2026.08","sections":[{"title":"1. Funções dão nomes a responsabilidades","body":"Centralize tarefas reutilizáveis e evite duplicar regras. Nome e escopo devem comunicar intenção."},{"title":"2. Parâmetros definem entradas","body":"Parâmetros fazem parte do contrato; argumentos são valores concretos fornecidos em cada chamada."},{"title":"3. Retornos conectam etapas","body":"Valores retornados podem alimentar cálculos, decisões e outras funções."},{"title":"4. Listas representam coleções variáveis","body":"Use quando vários valores relacionados precisam ser percorridos ou processados sem quantidade fixa."},{"title":"5. Buscar, filtrar e transformar têm saídas diferentes","body":"Defina primeiro o que deseja produzir para escolher o padrão correto."},{"title":"6. Composição conecta partes pequenas","body":"Fluxos maiores devem continuar testáveis por meio de responsabilidades e contratos claros."},{"title":"7. Solução completa começa pelo problema","body":"No desafio final, escolha estruturas pela necessidade da triagem, não porque o curso ensinou uma lista de comandos."},{"title":"Exercícios","items":["Transforme uma regra repetida em função.","Crie uma função que receba valores e retorne um cálculo.","Modele uma lista de pedidos e filtre os concluídos.","Componha validação, cálculo e classificação em funções separadas."]}]}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) and position=1;
update nexora.learning_resources set title='Guia de composição de soluções',summary='Checklist para transformar fundamentos isolados em um fluxo completo e testável.',content='{"editorial_version":"lc-editorial-2026.08","sections":[{"title":"Antes de codificar","items":["Qual é a entrada completa?","Quais validações devem acontecer primeiro?","Quais responsabilidades merecem funções?","Quais dados são coleções?","Onde existem decisões e repetições?","Qual resultado cada etapa entrega à próxima?","Quais testes isolados e integrados serão usados?"]},{"title":"Sinais de acoplamento excessivo","items":["Função com muitas responsabilidades.","Estado global alterado por vários pontos.","Mesma regra copiada em lugares diferentes.","Laço que busca, filtra, soma e altera interface ao mesmo tempo.","Dificuldade de testar uma etapa sem executar todo o sistema."]}]}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) and position=2;
update nexora.learning_resources set title='Projeto guiado — Triagem de atendimentos',summary='Projeto integrador do curso para demonstrar lógica aplicada antes da Boss Fight.',content='{"editorial_version":"lc-editorial-2026.08","sections":[{"title":"Objetivo","body":"Produza um algoritmo reproduzível para ordenar atendimentos por prioridade e chegada, validar dados e gerar indicadores."},{"title":"Entradas","items":["Nome.","Idade.","Tipo de solicitação.","Horário de chegada."]},{"title":"Regras","items":["Idade 60 ou mais tem prioridade.","Dentro da mesma categoria, preserve a ordem de chegada.","Idades inválidas não entram na fila normal.","Conte total e quantidade prioritária."]},{"title":"Entrega","items":["Fluxo ou pseudocódigo completo.","Decomposição em funções ou etapas.","Casos de teste normais, fronteiras e inválidos.","Explicação curta dos contratos de cada parte."]}]}'::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) and position=3;
update nexora.projects set title='Boss Fight — Algoritmo de triagem',description='Construa uma solução completa e verificável para um problema de triagem ou atendimento. A entrega deve demonstrar modelagem de dados, validação, decisões, repetição, funções e coleções. Não é uma redação: entregue pseudocódigo, fluxograma, código ou outro artefato executável/demonstrável, acompanhado de casos de teste e uma explicação curta de como reproduzir o resultado.',rubric='{"criteria":[{"label":"Modelagem e decomposição","weight":20},{"label":"Correção das regras","weight":25},{"label":"Uso coerente dos fundamentos","weight":20},{"label":"Testes e casos de fronteira","weight":20},{"label":"Clareza e reprodutibilidade","weight":15}]}'::jsonb,xp_reward=400 where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=5 limit 1) and project_kind='boss_fight';
commit;
